function ExampleCard({ title, children }: { title: string; description: string; icon: React.ReactNode; children: React.ReactNode }) {
  return <div data-example={title} className="w-full">{children}</div>;
}

function DurationPicker() {
  const [open, setOpen] = useState(false);
  const [start, setStart] = useState("02:00 AM");
  const [duration, setDuration] = useState("30 min");
  const [endOverride, setEndOverride] = useState("");
  const presets = [["30 min", 30], ["2 hours", 120], ["4 hours", 240], ["8 hours", 480], ["12 hours", 720], ["1 day", 1440]] as const;
  const startOptions = ["02:00 AM", "08:00 AM", "09:00 AM", "10:00 AM", "12:00 PM", "02:00 PM"];
  const startMinutes = (() => { const [clock, meridiem] = start.split(" "); const [hours, minutes] = clock.split(":").map(Number); return ((hours % 12) + (meridiem === "PM" ? 12 : 0)) * 60 + minutes; })();
  const durationMinutes = presets.find(([label]) => label === duration)?.[1] ?? 30;
  const endMinutes = (startMinutes + durationMinutes) % 1440;
  const endHour = Math.floor(endMinutes / 60);
  const calculatedEndTime = `${String(endHour % 12 || 12).padStart(2, "0")}:${String(endMinutes % 60).padStart(2, "0")} ${endHour >= 12 ? "PM" : "AM"}`;
  const endTime = endOverride || calculatedEndTime;
  const endOptions = [...new Set([calculatedEndTime, "02:30 AM", "04:00 AM", "08:00 AM", "10:00 AM", "12:00 PM", "02:00 PM", "04:00 PM", "08:00 PM"])];
  return <ExampleCard title="Duration Picker" description="Choose a start and end time, or use a quick preset." icon={<IconCalendarTime className="size-4" />}><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm">{start} – {endTime}</p><Button onClick={() => setOpen(true)}>Choose time</Button></div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="gap-0 p-0 sm:!max-w-[576px]"><DialogHeader className="p-4 pb-3"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-lg border bg-muted/40"><IconCalendarTime className="size-5" /></span><div className="grid gap-1"><DialogTitle>Select duration</DialogTitle><DialogDescription>Pick a start and end time or use a quick preset.</DialogDescription></div></div></DialogHeader><div className="grid gap-5 p-4 pt-2"><div className="grid grid-cols-2 gap-4"><label className="grid gap-1.5 text-sm">Start time (optional)<Select value={start} onValueChange={value => { setStart(value); setEndOverride(""); }}><SelectTrigger aria-label="Start time" className="w-full"><SelectValue /></SelectTrigger><SelectContent>{startOptions.map(time => <SelectItem key={time} value={time}>{time}</SelectItem>)}</SelectContent></Select></label><label className="grid gap-1.5 text-sm">End time (optional)<Select value={endTime} onValueChange={setEndOverride}><SelectTrigger aria-label="End time" className="w-full"><SelectValue /></SelectTrigger><SelectContent>{endOptions.map(time => <SelectItem key={time} value={time}>{time}</SelectItem>)}</SelectContent></Select></label></div><fieldset className="grid gap-2"><legend className="text-sm">Quick duration</legend><div className="grid grid-cols-2 gap-2 sm:grid-cols-4">{presets.map(([preset]) => <Button key={preset} type="button" variant={duration === preset ? "secondary" : "outline"} size="sm" onClick={() => { setDuration(preset); setEndOverride(""); }}>{preset}</Button>)}</div></fieldset></div><DialogFooter className="!mx-0 !mb-0 items-center justify-between sm:justify-between"><p className="text-xs text-muted-foreground">Quick presets update the end time.</p><div className="flex gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button onClick={() => setOpen(false)}>Apply</Button></div></DialogFooter></DialogContent></Dialog></ExampleCard>;
}

function BulkInvite() {
  const [open, setOpen] = useState(false);
  const [emailInput, setEmailInput] = useState("");
  const [role, setRole] = useState("member");
  const invitees = [...new Set(emailInput.split(/[\s,;]+/).map(value => value.trim()).filter(value => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(value)))];
  return <ExampleCard title="Bulk Email Invite" description="Invite teammates and choose their workspace role." icon={<IconMail className="size-4" />}><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-sm text-muted-foreground">{invitees.length ? invitees.length + " invitation" + (invitees.length === 1 ? "" : "s") + " ready" : "No pending invitations"}</p><Button onClick={() => setOpen(true)}>Invite people</Button></div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="gap-0 p-0 sm:!max-w-[448px]"><DialogHeader className="p-4 pb-3"><div className="flex items-center gap-2"><DialogTitle>Invite teammates</DialogTitle><Badge variant="warning-light">Workspace access</Badge></div><DialogDescription>Add an email and choose the role they start with.</DialogDescription></DialogHeader><div className="grid gap-3 p-4 pt-1"><label className="grid gap-1.5 text-sm">Invite by email<Input aria-label="Invite by email" type="text" inputMode="email" placeholder="name@company.com" value={emailInput} onChange={event => setEmailInput(event.target.value)} /></label><label className="grid gap-1.5 text-sm">Invite as<Select value={role} onValueChange={setRole}><SelectTrigger className="w-full"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="member">Core member</SelectItem><SelectItem value="admin">Administrator</SelectItem><SelectItem value="viewer">Viewer</SelectItem></SelectContent></Select></label></div><DialogFooter className="!mx-0 !mb-0"><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={!invitees.length} onClick={() => { setOpen(false); toast.success(invitees.length + " invitation" + (invitees.length === 1 ? "" : "s") + " ready"); }}>Send {invitees.length > 1 ? invitees.length + " invites" : "invite"}</Button></DialogFooter></DialogContent></Dialog></ExampleCard>;
}

function CancelPlanSurvey() {
  const [open, setOpen] = useState(false);
  const [reasons, setReasons] = useState<string[]>([]);
  const [showNotice, setShowNotice] = useState(true);
  const options = ["Only needed one launch", "Budget changed", "Missing a few patterns", "Moved back in-house", "Not the right stack fit", "Wanted better Figma parity", "Output felt inconsistent", "Something else"];
  return <ExampleCard title="Cancel Plan Survey" description="Collect cancellation feedback before ending a subscription." icon={<IconX className="size-4" />}><div className="flex items-center justify-between gap-3"><div><p className="text-sm font-medium">Northstar Pro</p><p className="text-sm text-muted-foreground">Renews on November 30</p></div><Button variant="outline" onClick={() => setOpen(true)}>Cancel plan</Button></div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="gap-0 p-0 sm:!max-w-[672px]"><DialogHeader className="p-5 pb-4"><DialogTitle>Cancel Your Plan</DialogTitle><DialogDescription>Your workspace stays active through the current billing period.</DialogDescription></DialogHeader><div className="grid gap-5 px-5 pb-5">{showNotice && <div className="flex flex-wrap items-center gap-3 rounded-lg border border-warning/40 bg-warning/5 p-3"><IconInfoCircle className="size-4 shrink-0 text-warning" /><div className="min-w-0 flex-1"><p className="text-sm font-medium">Shared access pauses after expiry.</p><p className="text-sm text-muted-foreground">Team access stays on until the current period ends.</p></div><Button type="button" size="sm" variant="outline" onClick={() => setShowNotice(false)}>Dismiss</Button><Button type="button" size="sm" onClick={() => { setOpen(false); toast("Your billing settings are ready to manage."); }}>Manage</Button></div>}<fieldset className="grid grid-cols-1 gap-2 sm:grid-cols-2"><legend className="mb-3 text-sm font-medium">Select cancellation reasons</legend>{options.map(reason => <label key={reason} className="flex min-h-10 items-center justify-between gap-3 rounded-lg border px-3 py-2 text-sm"><span>{reason}</span><Checkbox checked={reasons.includes(reason)} onCheckedChange={checked => setReasons(current => checked ? [...current, reason] : current.filter(item => item !== reason))} /></label>)}</fieldset><label className="grid gap-2 text-sm font-medium">Additional feedback<Textarea placeholder="Anything we should improve before you leave?" rows={3} /></label></div><DialogFooter className="!mx-0 !mb-0 items-center justify-between sm:justify-between"><p className="text-sm text-muted-foreground">Billing stays active</p><div className="flex gap-2"><Button variant="outline" onClick={() => setOpen(false)}>Keep plan</Button><Button variant="destructive" disabled={!reasons.length} onClick={() => { setOpen(false); toast("Cancellation request saved for this preview."); }}>Cancel plan</Button></div></DialogFooter></DialogContent></Dialog></ExampleCard>;
}

function LaunchChecklist() {
  const [open, setOpen] = useState(false);
  const [connectedApps, setConnectedApps] = useState<string[]>([]);
  const [fallback, setFallback] = useState(false);
  const [editing, setEditing] = useState<string | null>(null);
  const [values, setValues] = useState({ owner: "Ari Mendoza", alias: "growth-command", window: "Tue, 10:00 UTC" });
  const sections = [
    { id: "ownership", title: "Ownership & cadence", description: "Lock in the primary operator, workspace alias, and review window.", icon: <IconShieldCheck className="size-4" />, status: "In progress" },
    { id: "apps", title: "Connected apps", description: "Choose the tools that can send events or receive rollout updates.", icon: <IconRoute2 className="size-4" />, status: connectedApps.length ? "Complete" : "Pending" },
    { id: "fallback", title: "Fallback rules", description: "Set where alerts and digests land if the primary flow is paused.", icon: <IconBellRinging className="size-4" />, status: fallback ? "Complete" : "Pending" },
  ];
  const fieldRows = [["owner", "Launch owner", <IconUser key="owner-icon" className="size-4" />], ["alias", "Workspace alias", <IconBuilding key="alias-icon" className="size-4" />], ["window", "Review window", <IconCalendarTime key="window-icon" className="size-4" />]] as const;
  return <ExampleCard title="Launch Checklist" description="Review workspace setup and connected services." icon={<IconCheck className="size-4" />}><div className="flex items-center justify-between gap-3"><p className="text-sm text-muted-foreground">Ownership, connected apps, and fallback rules</p><Button onClick={() => setOpen(true)}>Review setup</Button></div><Dialog open={open} onOpenChange={setOpen}><DialogContent className="max-h-[90vh] min-h-[min(550px,85vh)] gap-0 overflow-y-auto p-0 sm:!max-w-[600px]"><DialogHeader className="p-4 pb-2"><DialogTitle>Launch checklist</DialogTitle><DialogDescription>Finalize routing, apps, and fallback rules before launch.</DialogDescription></DialogHeader><Accordion type="multiple" defaultValue={["ownership"]} className="justify-between px-4 pb-4 pt-1.5">{sections.map(section => <AccordionItem key={section.id} value={section.id} className="not-last:border-b-0"><AccordionTrigger className="items-start py-3 hover:no-underline"><div className="flex min-w-0 flex-1 items-start gap-3 text-left"><span className="grid size-10 shrink-0 place-items-center rounded-lg border bg-muted/30">{section.icon}</span><span className="min-w-0 flex-1"><span className="flex items-center gap-2 text-sm font-medium">{section.title}{section.id === "ownership" && <Badge variant="success-light">{section.status}</Badge>}</span><span className={`mt-1 block ${section.id === "apps" ? "max-w-[24rem]" : "max-w-[22rem]"} text-sm font-normal leading-5 text-muted-foreground`}>{section.description}</span></span>{section.id !== "ownership" && <Badge className="mr-2 mt-1 shrink-0" variant={section.status === "Pending" ? "secondary" : "success-light"}>{section.status}</Badge>}</div></AccordionTrigger><AccordionContent className="pb-3 pl-[52px]">{section.id === "ownership" ? <div className="divide-y rounded-lg border px-3">{fieldRows.map(([key, label, Icon]) => <div key={key} className="grid min-h-9.5 grid-cols-[1fr_1fr] items-center gap-3 text-sm"><span className="flex items-center gap-2 text-muted-foreground">{Icon}{label}</span>{editing === key ? <Input aria-label={label} autoFocus value={values[key]} onChange={event => setValues(current => ({ ...current, [key]: event.target.value }))} onBlur={() => setEditing(null)} onKeyDown={event => { if (event.key === "Enter") setEditing(null); }} className="h-8" /> : <button type="button" onClick={() => setEditing(key)} className="text-left text-muted-foreground hover:text-foreground">{values[key]}</button>}</div>)}</div> : section.id === "apps" ? <div className="grid gap-2 rounded-lg border p-3">{([["analytics", "Product analytics"], ["notifications", "Release notifications"]] as const).map(([id, label]) => <label key={id} className="flex items-center gap-2 text-sm"><Checkbox checked={connectedApps.includes(id)} onCheckedChange={checked => setConnectedApps(current => checked ? [...current, id] : current.filter(app => app !== id))} />{label}</label>)}</div> : <div className="grid gap-3 rounded-lg border p-3"><label className="grid gap-1 text-sm">Fallback channel<Select defaultValue="slack" onValueChange={() => setFallback(true)}><SelectTrigger className="w-full"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="slack">Slack · #launch-ops</SelectItem><SelectItem value="email">Email digest</SelectItem></SelectContent></Select></label><label className="flex items-center gap-2 text-sm"><Checkbox checked={fallback} onCheckedChange={checked => setFallback(checked === true)} />Send a daily fallback digest</label></div>}</AccordionContent></AccordionItem>)}</Accordion><DialogFooter className="!mx-0 !mb-0 items-center px-5"><Button size="sm" variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button size="sm" onClick={() => { setOpen(false); toast.success("Launch checklist saved"); }}>Save</Button></DialogFooter></DialogContent></Dialog></ExampleCard>;
}

