function TemplateLibrary() {
  const [open, setOpen] = useState(false);
  const [category, setCategory] = useState<string>("all");
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState("");
  const [fullscreen, setFullscreen] = useState(false);
  const filtered = templates.filter(template => (category === "all" || template.category === category) && `${template.name} ${template.description} ${template.audience} ${template.tags.join(" ")}`.toLowerCase().includes(query.toLowerCase()));
  const selectedTemplate = templates.find(template => template.id === selected);
  const surfaces = ["bg-primary/10 text-primary", "bg-destructive/10 text-destructive", "bg-warning/10 text-warning", "bg-success/10 text-success", "bg-info/10 text-info", "bg-warning/10 text-warning", "bg-info/10 text-info", "bg-primary/10 text-primary"];
  return <ExampleCard title="Template Library" description="Browse starter templates and choose a project structure." icon={<IconSearch className="size-4" />}><div className="flex items-center justify-between gap-3"><p className="text-sm text-muted-foreground">{templates.length} starter templates</p><Button onClick={() => setOpen(true)}>Browse templates</Button></div><Dialog open={open} onOpenChange={setOpen}><DialogContent showCloseButton={false} className={`grid w-[calc(100vw-2rem)] grid-rows-[auto_minmax(0,1fr)_auto] gap-0 overflow-hidden p-0 ${fullscreen ? "h-[100dvh] max-h-[100dvh] rounded-none sm:!max-w-none" : "h-[min(90vh,56rem)] max-h-[90vh] sm:!max-w-[1024px]"}`}><DialogHeader className="flex-row items-center justify-between gap-4 border-b px-5 py-4"><div className="grid gap-1"><DialogTitle>Starter library</DialogTitle><DialogDescription>Choose a ready operating shape, then tailor it to your team.</DialogDescription></div><Button variant="ghost" size="icon" aria-label={fullscreen ? "Exit full screen" : "Enter full screen"} onClick={() => setFullscreen(value => !value)}>{fullscreen ? <IconMinimize className="size-4" /> : <IconMaximize className="size-4" />}</Button></DialogHeader><div className="grid min-h-0 grid-cols-1 grid-rows-[auto_minmax(0,1fr)] md:grid-cols-[18rem_minmax(0,1fr)] md:grid-rows-1"><nav aria-label="Template use cases" className="grid grid-flow-col auto-cols-[14rem] content-start gap-1 overflow-x-auto border-b p-3 md:grid-flow-row md:auto-cols-auto md:overflow-y-auto md:border-b-0 md:border-r"><p className="px-2.5 pb-1 pt-1 text-xs font-medium text-muted-foreground">Use cases</p>{templateCategories.map((item, index) => <Button key={item.id} type="button" variant="ghost" aria-pressed={category === item.id} onClick={() => setCategory(item.id)} className={`h-[54px] w-full shrink-0 justify-start gap-2.5 px-2.5 text-left ${category === item.id ? "bg-muted hover:bg-muted" : "hover:bg-muted/60"}`}><span className={`grid size-9 shrink-0 place-items-center rounded-lg ${surfaces[index]}`}><span className="size-3 rounded-[3px] border-2 border-current" /></span><span className="grid min-w-0 gap-0.5"><span className="truncate text-sm font-medium">{item.name}</span><span className="truncate text-xs font-normal text-muted-foreground">{item.detail}</span></span></Button>)}</nav><div className="flex min-h-0 min-w-0 flex-col p-5"><label className="relative mb-3 block shrink-0"><IconSearch className="absolute left-3 top-2.5 size-4 text-muted-foreground" /><Input aria-label="Search templates, workflows, or teams" placeholder="Search templates, workflows, or teams..." value={query} onChange={event => setQuery(event.target.value)} className="h-8 pl-9" /></label><div className="min-h-0 flex-1 space-y-2 overflow-y-auto pr-1">{filtered.map(template => <button key={template.id} type="button" aria-pressed={selected === template.id} onClick={() => setSelected(template.id)} className={`grid min-h-[118px] w-full grid-cols-[4rem_minmax(0,1fr)] items-start gap-3 rounded-xl border p-3 text-left transition-colors sm:grid-cols-[8rem_minmax(0,1fr)] ${selected === template.id ? "border-primary bg-primary/5" : "hover:bg-muted/30"}`}><span className="h-12 w-16 rounded-lg bg-muted/50 sm:h-20 sm:w-32" aria-hidden="true" /><span className="min-w-0"><span className="flex items-center gap-2"><span className="truncate text-sm font-semibold">{template.name}</span><Badge className="ml-auto shrink-0" variant="outline">{template.audience}</Badge></span><span className="mt-1 block max-w-[32rem] text-sm leading-5 text-muted-foreground">{template.description}</span><span className="mt-2 flex flex-wrap gap-1.5">{template.tags.map((tag, index) => <Badge key={tag} variant={index === 0 ? "secondary" : "outline"} className={index === 1 ? "border-info/20 bg-info/5 text-info" : index === 2 ? "border-warning/20 bg-warning/5 text-warning" : ""}>{tag}</Badge>)}</span></span></button>)}{!filtered.length && <p className="py-8 text-center text-sm text-muted-foreground">No templates match your search.</p>}</div></div></div><DialogFooter className="!mx-0 !mb-0 items-center border-t px-5 py-3"><span className="mr-auto text-sm text-muted-foreground">{selectedTemplate ? `Selected: ${selectedTemplate.name}` : "Select a starter template"}</span><Button variant="outline" onClick={() => setOpen(false)}>Cancel</Button><Button disabled={!selectedTemplate} onClick={() => { setOpen(false); toast.success(`${selectedTemplate?.name} selected`); }}>Use template</Button></DialogFooter></DialogContent></Dialog></ExampleCard>;
}

